package pgi3pilot

import "testing"

func TestNormalizeLabel(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"empty", "", ""},
		{"ascii spaces", "  Keep  Case  ", "Keep  Case"},
		{"ascii whitespace", "\t\r\nKeep  Case\v\f", "Keep  Case"},
		{"unicode boundaries", "\u00a0\u2003Keep  Case\u202f\u3000", "Keep  Case"},
		{"leading only", "\u0085Étiquette", "Étiquette"},
		{"trailing only", "标签\u2028\u2029", "标签"},
		{"whitespace only", " \t\u0085\u00a0\u1680\u2003\u2028\u2029\u202f\u205f\u3000\n", ""},
		{"interior preserved", "\u2003Keep\t \n\u00a0\u2003Case\u3000", "Keep\t \n\u00a0\u2003Case"},
		{"unchanged", "MiXeD\t\u00a0标签", "MiXeD\t\u00a0标签"},
		{"non whitespace boundaries", "\u200bKeep Case\ufeff", "\u200bKeep Case\ufeff"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := NormalizeLabel(tt.in); got != tt.want {
				t.Errorf("NormalizeLabel(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}
